/**
 * Under the Palm
 * --------------
 * Deborah, a prophetess and judge, sits beneath the Palm of Deborah between Ramah and Bethel, hearing the disputes of Israel. Stage: a broad palm casting dappled shade over limestone benches, Israelites climbing the hill country to seek judgment; warm late-morning light, olive-green and distant blue hills.
 *
 * Palette 0xd8b878 → 0x9c8456 · light: dawn · hero: tree
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./deborah-kit.js.
 */

import { THREE, createScene, cityGate, house, palm, oak, person, crowd, birds } from './deborah-kit.js';

const BG = 0xd8b878;
const GROUND = 0x776542;

export function build(group) {
    const W = createScene(group, { seed: 290728685, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — dawn */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-58, 30, -145], 9, 0xffd9a0);
    W.disc([-58, 30, -155], 16, 0xffb060, 0.22);
    W.stars(60, 150, [0xcfd8e8, 0xbfd0e0], 0.55);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-60, 34, -120, 24], [10, 40, -135, 30], [70, 33, -125, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xd8c8b8, { opacity: 0.5 }), [x, y, z], { s: [s, s * 0.24, s * 0.5] });
    });
    W.backdrop(clouds);

    /* ground */
    W.ground(260, 260, 0, 0, 0x776542, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* hills: angular ridges on the horizon */
    const hills = W.grp(group, [0, 0, 0], { name: 'hills' });
    for (let i = 0; i < 9; i++) {
        const x = -130 + i * 32 + W.rr(-8, 8);
        W.add(hills, W.G('cone', W.rr(14, 28), W.rr(10, 24), 5), W.mat(0x594c32), [x, 0, -95 - W.rr(0, 25)], { r: [0, W.r() * 3, 0] });
    }
    W.backdrop(hills);

    /* city: gate, towers and houses on the far side */
    const city = W.grp(group, [-12, 0, -58], { name: 'city', r: [0, -0.13, 0] });
    cityGate(W, city, 0, 0, 0, 1.15, { stone: 0xa48b5a, trim: 0x5f5135 });
    for (let i = 0; i < 5; i++) {
        house(W, city, -34 + i * 17 + W.rr(-4, 4), 0, W.rr(-14, 6), 0.85 + W.r() * 0.4, { mud: 0x947d52 });
    }
    W.backdrop(city);

    /* palms: dappled shade at the scene's edge */
    palm(W, group, -54.6, 0, -1.2, 1.50, { leafA: 0x4f8a2e, leafB: 0x5fa036 });
    palm(W, group, 80.8, 0, -64.7, 1.03, { leafA: 0x4f8a2e, leafB: 0x5fa036 });
    palm(W, group, -76.0, 0, -24.0, 1.16, { leafA: 0x4f8a2e, leafB: 0x5fa036 });
    palm(W, group, -60.4, 0, -5.4, 1.42, { leafA: 0x4f8a2e, leafB: 0x5fa036 });
    palm(W, group, -36.0, 0, -22.0, 1.03, { leafA: 0x4f8a2e, leafB: 0x5fa036 });
    palm(W, group, 70.9, 0, -19.9, 1.16, { leafA: 0x4f8a2e, leafB: 0x5fa036 });
    palm(W, group, 19.5, 0, 6.8, 1.03, { leafA: 0x4f8a2e, leafB: 0x5fa036 });
    /* trees: broadleaf shade */
    oak(W, group, -49.3, 0, -38.3, 1.14, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, 56.6, 0, -24.3, 1.25, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, -24.2, 0, -52.9, 1.01, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });

    /* hero: the great tree */
    oak(W, group, 0, 0, 0, 1.7, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    W.disc([0, 8, -16], 9, 0xffef9c, 0.25);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x8a6a44, head: 'wrap', wrap: 0xf8d48a, wrapTrim: 0x978154, beard: 'long', staff: 'planted', bend: 1.05, armR: [0.2, 0.1], armL: [0.2, -0.1], ry: 0.08, s: 1.00 });
    /* crowd: the people of the story */
    crowd(W, group, 0, 16, 16, 70, 44, [0xd8b878, 0x9c8456, 0x776542, 0x8a6a44, 0x6a4a30, 0xc8b088]);

    /* birds: slow circles high above */
    birds(W, group, 7, 55, { y: 26 });

    return W.finish();
}

export default { build };
